import { useState, useEffect } from 'react';

export function Comentarios({ postId }) {
  const [comentarios, setComentarios] = useState([]);

  useEffect(() => {
    fetch(`/api/posts/${postId}/comentarios`)
      .then((res) => res.json())
      .then(setComentarios);
  }, [postId]);

  return (
    <section>
      <h3>Comentarios ({comentarios.length})</h3>
      {comentarios.map((c) => (
        <article key={c.id}>
          <a href={c.autorWeb}>{c.autor}</a>
          <div dangerouslySetInnerHTML={{ __html: c.texto }} />
          <time>{new Date(c.fecha).toLocaleDateString()}</time>
        </article>
      ))}
    </section>
  );
}

